insert into offer_candidates (candidate_key, account_id, source_id, source_url, destination_url, canonical_domain, vendor_name, offer_title, offer_summary, category_key, trend_lane, monetization_status, payout_model, payout_notes, account_status, approval_status, image_rights_status, disclosure_required, disclosure_text, risk_tier, publish_decision, claim_restrictions, missing_data, candidate_score, candidate_confidence, false_positive_risks, scoring_inputs, source_age_hours, privacy_pii_handling, last_reviewed_at)
select c.candidate_key, a.id, s.id, c.source_url, c.destination_url, c.canonical_domain, c.vendor_name, c.offer_title, c.offer_summary, c.category_key, c.trend_lane, c.monetization_status, c.payout_model, c.payout_notes, c.account_status, c.approval_status, c.image_rights_status, c.disclosure_required, c.disclosure_text, c.risk_tier, c.publish_decision, c.claim_restrictions, c.missing_data, c.candidate_score, c.candidate_confidence, c.false_positive_risks, c.scoring_inputs::jsonb, c.source_age_hours, c.privacy_pii_handling, now()
from amazon_manual_offer_cards c
join offer_accounts a on a.account_key = c.account_key
join offer_sources s on s.source_key = c.source_key
on conflict (candidate_key) do update set
  monetization_status = excluded.monetization_status,
  approval_status = excluded.approval_status,
  image_rights_status = excluded.image_rights_status,
  publish_decision = excluded.publish_decision,
  destination_url = excluded.destination_url,
  updated_at = now();

with amazon_manual_tracking(candidate_key, tracking_key, go_slug, destination_url, destination_domain, payout_model, monetization_status, disclosure_version) as (
select
  c.candidate_key,
  replace(c.candidate_key, 'amazon-manual-', 'tracking-amazon-') as tracking_key,
  replace(c.candidate_key, 'amazon-manual-', 'amazon-') as go_slug,
  c.destination_url,
  'amazon.com' as destination_domain,
  'commission' as payout_model,
  'approved_monetized' as monetization_status,
  'spg-affiliate-disclosure-v1' as disclosure_version
from offer_candidates c
where c.candidate_key like 'amazon-manual-amazon-%'
)
insert into affiliate_tracking (tracking_key, candidate_id, account_id, go_slug, destination_url, destination_domain, payout_model, monetization_status, disclosure_required, disclosure_version, tracking_status, approval_status, risk_tier, utm_template, last_health_status, last_health_checked_at)
select t.tracking_key, c.id, c.account_id, t.go_slug, t.destination_url, t.destination_domain, t.payout_model, t.monetization_status, true, t.disclosure_version, 'active', 'approved', c.risk_tier, '{"source":"spg","medium":"go_bridge","campaign":"amazon_manual"}'::jsonb, 'manual_review', now()
from amazon_manual_tracking t
join offer_candidates c on c.candidate_key = t.candidate_key
on conflict (tracking_key) do update set
  destination_url = excluded.destination_url,
  tracking_status = excluded.tracking_status,
  approval_status = excluded.approval_status,
  updated_at = now();

insert into publish_decisions (candidate_id, affiliate_tracking_id, publish_decision, approval_status, decision_reason, decision_by_role, route_path, surface, starts_at, risk_tier)
select c.id, at.id, 'publish_monetized', 'approved', 'Amazon manual bridge card has active Associates account reference, visible disclosure, approved tag label, and no copied merchant content.', 'DataEng', '/go/' || at.go_slug || '.html', 'go_bridge', now(), c.risk_tier
from offer_candidates c
join affiliate_tracking at on at.candidate_id = c.id and at.tracking_key = replace(c.candidate_key, 'amazon-manual-', 'tracking-amazon-')
where c.candidate_key like 'amazon-manual-amazon-%'
  and not exists (
    select 1 from publish_decisions pd
    where pd.candidate_id = c.id
      and pd.affiliate_tracking_id = at.id
      and pd.surface = 'go_bridge'
  );

